#!/usr/bin/env node
/**
 * Task-local runner: initialize the slack-api skill skeleton via the
 * skill-creator's init_skill.cjs, then remove the placeholder example files
 * (they will be replaced with real content written in this episode).
 */
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');

const cwd = process.cwd();
const initScript = path.join(cwd, '.codex/skills/skill-creator/scripts/init_skill.cjs');
const skillDir = path.join(cwd, 'slack-api');

const res = spawnSync(process.execPath, [initScript, 'slack-api', '--path', cwd], {
  cwd,
  encoding: 'utf8',
});
process.stdout.write(res.stdout || '');
process.stderr.write(res.stderr || '');
if (res.status !== 0) {
  process.exit(res.status || 1);
}

// Remove placeholder example files; real files are written next.
const placeholders = [
  path.join(skillDir, 'scripts/example_script.cjs'),
  path.join(skillDir, 'references/example_reference.md'),
  path.join(skillDir, 'assets/example_asset.txt'),
];
for (const p of placeholders) {
  if (fs.existsSync(p)) fs.unlinkSync(p);
}
try {
  fs.rmdirSync(path.join(skillDir, 'assets'));
} catch {
  /* assets dir may already be gone */
}

const remaining = fs.readdirSync(skillDir).sort();
console.log('Skill skeleton ready at ' + skillDir);
console.log('Remaining entries: ' + remaining.join(', '));

